#!/usr/bin/env python3
"""Parche local RKP. Uso: python parche_rutinas.py --raiz E:\\xampp\\htdocs\\RKP [--aplicar]
Sin --aplicar solo verifica. No usa Git ni modifica .env.
"""
import argparse, ast, hashlib, json, shutil
from pathlib import Path
from datetime import datetime
PAYLOAD = json.loads('{"iniciar_rutinas.py": {"sha256": "d2c330a79cd42ca03df22c0dc83cf5098d543c0cca9bb275e394796ff4991841", "content": "#!/usr/bin/env python3\\n\\"\\"\\"Lanzador de rutinas de RKP: ejecuta periódicamente todas las rutinas registradas.\\n\\nCada rutina corre como un proceso aparte (python -m <modulo> <args>), con:\\n  - intervalo alineado al reloj, como cron (cada 30 min -> :00 y :30),\\n  - un solo proceso a la vez por rutina (si sigue corriendo, se salta el turno),\\n  - tiempo máximo (si lo supera, se detiene),\\n  - log propio en data/rutinas/<nombre>.log (rotado al pasar de 10 MB).\\n\\nAgregar una rutina: añadir una entrada a RUTINAS (abajo).\\nAjustar sin tocar código, en el .env de RKP:\\n  RUTINA_<NOMBRE>_HABILITADA=true|false\\n  RUTINA_<NOMBRE>_CADA_MINUTOS=30\\n  RUTINA_<NOMBRE>_TIMEOUT_MINUTOS=25\\n  RUTINAS_PYTHON=C:\\\\\\\\ruta\\\\\\\\python.exe   (opcional; por defecto el Python que ejecuta este archivo)\\n\\nUso (desde la raíz de RKP):\\n  python iniciar_rutinas.py                 inicia el lanzador (queda corriendo)\\n  python iniciar_rutinas.py --listar        muestra rutinas, intervalos y próxima ejecución\\n  python iniciar_rutinas.py --ahora NOMBRE  ejecuta una rutina una vez y muestra su salida\\n\\"\\"\\"\\nfrom __future__ import annotations\\n\\nimport argparse\\nimport os\\nimport re\\nimport signal\\nimport subprocess\\nimport sys\\nimport threading\\nimport time\\nfrom dataclasses import dataclass, field\\nfrom datetime import datetime, timedelta\\nfrom pathlib import Path\\n\\nRAIZ = Path(__file__).resolve().parent\\n\\n# =====================================================================\\n# RUTINAS REGISTRADAS\\n#   nombre           identificador corto (letras, números y _); se usa en el .env y en el log\\n#   modulo           módulo Python que se ejecuta con \\"python -m\\"\\n#   argumentos       argumentos del módulo\\n#   cada_minutos     intervalo; alineado al reloj (30 -> :00 y :30, 15 -> :00 :15 :30 :45)\\n#   desfase_minutos  corre N minutos después de cada marca (para no arrancar todas juntas)\\n#   timeout_minutos  si la ejecución supera este tiempo, se detiene\\n#   habilitada       valor por defecto (el .env lo puede cambiar)\\n# =====================================================================\\nRUTINAS = [\\n    {\\n        \\"nombre\\": \\"influx\\",\\n        \\"descripcion\\": \\"Consultas Influx centralizadas -> resultados compartidos\\",\\n        \\"modulo\\": \\"microservicios.rutina_influx\\",\\n        \\"argumentos\\": [\\"--ciclo\\"],\\n        \\"cada_minutos\\": 1,\\n        \\"cada_segundos\\": 30,\\n        \\"desfase_minutos\\": 0,\\n        \\"timeout_minutos\\": 120,\\n        \\"habilitada\\": True,\\n    },\\n    {\\n        \\"nombre\\": \\"dashboard_hfc\\",\\n        \\"descripcion\\": \\"Dashboard HFC: CASA + ARRIS por SSH -> MySQL rkp_hfc\\",\\n        \\"modulo\\": \\"microservicios.cmts.dashboard_hfc.rutina\\",\\n        \\"argumentos\\": [\\"--ciclo\\"],\\n        \\"cada_minutos\\": 10,\\n        \\"desfase_minutos\\": 0,\\n        \\"timeout_minutos\\": 25,\\n        \\"habilitada\\": True,\\n    },\\n    {\\n        \\"nombre\\": \\"estados_helix\\",\\n        \\"descripcion\\": \\"Estados Helix: API existente -> ultima lectura compartida\\",\\n        \\"modulo\\": \\"iniciar_rutinas\\",\\n        \\"argumentos\\": [\\"--ciclo-estados-helix\\"],\\n        \\"cada_minutos\\": 5,\\n        \\"desfase_minutos\\": 1,\\n        \\"timeout_minutos\\": 25,\\n        \\"habilitada\\": True,\\n    },\\n        {\\n        \\"nombre\\": \\"dashboard_hfc_helix\\",\\n        \\"descripcion\\": \\"Dashboard HFC: barrido global de casos Helix\\",\\n        \\"modulo\\": \\"microservicios.cmts.dashboard_hfc.casos_globales_helix\\",\\n        \\"argumentos\\": [\\n            \\"--full\\",\\n            \\"--batch-size\\", \\"300\\",\\n            \\"--budget\\", \\"180\\",\\n            \\"--retries\\", \\"1\\",\\n        ],\\n        \\"cada_minutos\\": 120,\\n        \\"desfase_minutos\\": 15,\\n        \\"timeout_minutos\\": 110,\\n        \\"habilitada\\": True,\\n    },\\n    {\\n        \\"nombre\\": \\"cmts_init\\",\\n        \\"descripcion\\": \\"Monitoreo INIT: ciclo global SSH -> CSV\\",\\n        \\"modulo\\": \\"iniciar_rutinas\\",\\n        \\"argumentos\\": [\\"--ciclo-cmts-init\\"],\\n        \\"cada_minutos\\": 15,\\n        \\"desfase_minutos\\": 0,\\n        \\"timeout_minutos\\": 120,\\n        \\"habilitada\\": False,\\n    },\\n    {\\n        \\"nombre\\": \\"topologias\\",\\n        \\"descripcion\\": \\"Materializa una topología aleatoria y convierte Visio a JPG\\",\\n        \\"modulo\\": \\"iniciar_rutinas\\",\\n        \\"argumentos\\": [\\"--ciclo-topologias\\"],\\n        \\"cada_minutos\\": 2,\\n        \\"desfase_minutos\\": 0,\\n        \\"timeout_minutos\\": 25,\\n        \\"habilitada\\": False,\\n    },\\n    # Ejemplo de la próxima rutina:\\n    # {\\n    #     \\"nombre\\": \\"otra_rutina\\",\\n    #     \\"descripcion\\": \\"Qué hace\\",\\n    #     \\"modulo\\": \\"microservicios.carpeta.rutina\\",\\n    #     \\"argumentos\\": [\\"--ciclo\\"],\\n    #     \\"cada_minutos\\": 15,\\n    #     \\"desfase_minutos\\": 5,\\n    #     \\"timeout_minutos\\": 12,\\n    #     \\"habilitada\\": True,\\n    # },\\n]\\n\\nCARPETA_LOGS = RAIZ / \\"data\\" / \\"rutinas\\"\\nLOG_MAX_BYTES = 10 * 1024 * 1024\\nCANDADO = CARPETA_LOGS / \\"iniciar_rutinas.lock\\"\\n\\n\\n# ============================================================== utilidades\\ndef _leer_env() -> dict[str, str]:\\n    \\"\\"\\"Lee el .env raíz con el mismo formato que microservicios/entorno.py.\\"\\"\\"\\n    ruta = RAIZ / \\".env\\"\\n    valores: dict[str, str] = {}\\n    if not ruta.is_file():\\n        return valores\\n    for linea in ruta.read_text(encoding=\\"utf-8-sig\\").splitlines():\\n        m = re.match(r\\"^\\\\s*(?:export\\\\s+)?([A-Za-z_][A-Za-z0-9_]*)\\\\s*=\\\\s*(.*?)\\\\s*$\\", linea)\\n        if not m:\\n            continue\\n        clave, valor = m.groups()\\n        if valor[:1] in (\'\\"\', \\"\'\\") and len(valor) > 1 and valor.rfind(valor[0]) > 0:\\n            valor = valor[1:valor.rfind(valor[0])]\\n        else:\\n            valor = re.split(r\\"\\\\s+#\\", valor, maxsplit=1)[0].rstrip()\\n        valores[clave] = valor\\n    return valores\\n\\n\\ndef _ahora() -> str:\\n    return datetime.now().strftime(\\"%Y-%m-%d %H:%M:%S\\")\\n\\n\\ndef _msg(texto: str) -> None:\\n    print(f\\"{_ahora()} [RUTINAS] {texto}\\", flush=True)\\n\\n\\n@dataclass\\nclass Rutina:\\n    nombre: str\\n    descripcion: str\\n    modulo: str\\n    argumentos: list[str]\\n    cada_minutos: int\\n    desfase_minutos: int\\n    timeout_minutos: int\\n    habilitada: bool\\n    cada_segundos: int = 0\\n    proceso: subprocess.Popen | None = None\\n    inicio: float = 0.0\\n    proxima: datetime | None = None\\n    ultima: str = \\"nunca\\"\\n    log: object = field(default=None, repr=False)\\n\\n    @property\\n    def ruta_log(self) -> Path:\\n        return CARPETA_LOGS / f\\"{self.nombre}.log\\"\\n\\n    def calcular_proxima(self, desde: datetime) -> datetime:\\n        \\"\\"\\"Siguiente marca alineada al reloj, estrictamente posterior a \'desde\'.\\"\\"\\"\\n        if self.cada_segundos:\\n            siguiente = (int(desde.timestamp()) // self.cada_segundos + 1) * self.cada_segundos\\n            return datetime.fromtimestamp(siguiente)\\n        base = desde.replace(second=0, microsecond=0)\\n        minutos_dia = base.hour * 60 + base.minute\\n        paso = self.cada_minutos\\n        siguiente = ((minutos_dia - self.desfase_minutos) // paso + 1) * paso + self.desfase_minutos\\n        return base.replace(hour=0, minute=0) + timedelta(minutes=siguiente)\\n\\n    def comando(self, python: str) -> list[str]:\\n        return [python, \\"-m\\", self.modulo, *self.argumentos]\\n\\n\\ndef cargar_rutinas(env: dict[str, str]) -> list[Rutina]:\\n    rutinas, vistos = [], set()\\n    for d in RUTINAS:\\n        nombre = d[\\"nombre\\"]\\n        if not re.fullmatch(r\\"[A-Za-z0-9_]+\\", nombre) or nombre.upper() in vistos:\\n            raise SystemExit(f\\"Nombre de rutina inválido o repetido: {nombre!r}\\")\\n        vistos.add(nombre.upper())\\n        prefijo = f\\"RUTINA_{nombre.upper()}_\\"\\n\\n        def entero(clave: str, defecto: int, minimo: int) -> int:\\n            valor = env.get(prefijo + clave, str(defecto)).strip()\\n            try:\\n                numero = int(valor)\\n            except ValueError:\\n                raise SystemExit(f\\"{prefijo}{clave} debe ser numérico\\") from None\\n            if numero < minimo:\\n                raise SystemExit(f\\"{prefijo}{clave} debe ser >= {minimo}\\")\\n            return numero\\n\\n        habilitada = env.get(prefijo + \\"HABILITADA\\", \\"true\\" if d.get(\\"habilitada\\", True) else \\"false\\")\\n        r = Rutina(\\n            nombre=nombre,\\n            descripcion=d.get(\\"descripcion\\", \\"\\"),\\n            modulo=d[\\"modulo\\"],\\n            argumentos=list(d.get(\\"argumentos\\", [])),\\n            cada_minutos=entero(\\"CADA_MINUTOS\\", int(d[\\"cada_minutos\\"]), 1),\\n            desfase_minutos=entero(\\"DESFASE_MINUTOS\\", int(d.get(\\"desfase_minutos\\", 0)), 0),\\n            timeout_minutos=entero(\\"TIMEOUT_MINUTOS\\", int(d.get(\\"timeout_minutos\\", d[\\"cada_minutos\\"])), 1),\\n            cada_segundos=entero(\\"CADA_SEGUNDOS\\", int(d.get(\\"cada_segundos\\", 0)), 0),\\n            habilitada=habilitada.strip().lower() in (\\"1\\", \\"true\\", \\"yes\\", \\"on\\", \\"si\\", \\"sí\\"),\\n        )\\n        if r.desfase_minutos >= r.cada_minutos:\\n            raise SystemExit(f\\"{nombre}: el desfase debe ser menor que el intervalo\\")\\n        rutinas.append(r)\\n    return rutinas\\n\\n\\ndef _abrir_log(r: Rutina):\\n    CARPETA_LOGS.mkdir(parents=True, exist_ok=True)\\n    if r.ruta_log.is_file() and r.ruta_log.stat().st_size > LOG_MAX_BYTES:\\n        anterior = r.ruta_log.with_suffix(\\".log.1\\")\\n        anterior.unlink(missing_ok=True)\\n        r.ruta_log.rename(anterior)\\n    return r.ruta_log.open(\\"a\\", encoding=\\"utf-8\\", errors=\\"replace\\")\\n\\n\\n# =========================================================== una instancia\\nclass Candado:\\n    \\"\\"\\"Impide dos lanzadores a la vez; el sistema lo libera aunque el proceso muera.\\"\\"\\"\\n\\n    def __init__(self, ruta: Path):\\n        ruta.parent.mkdir(parents=True, exist_ok=True)\\n        self.archivo = ruta.open(\\"a+b\\")\\n        try:\\n            if os.name == \\"nt\\":\\n                import msvcrt\\n\\n                self.archivo.seek(0)\\n                msvcrt.locking(self.archivo.fileno(), msvcrt.LK_NBLCK, 1)\\n            else:\\n                import fcntl\\n\\n                fcntl.flock(self.archivo, fcntl.LOCK_EX | fcntl.LOCK_NB)\\n        except OSError:\\n            self.archivo.close()\\n            raise SystemExit(\\"Ya hay un iniciar_rutinas.py corriendo en este equipo.\\") from None\\n        self.archivo.seek(0)\\n        self.archivo.truncate()\\n        self.archivo.write(f\\"pid={os.getpid()} inicio={_ahora()}\\\\n\\".encode())\\n        self.archivo.flush()\\n\\n\\n# ================================================================ ejecución\\ndef lanzar(r: Rutina, python: str) -> None:\\n    r.log = _abrir_log(r)\\n    r.log.write(f\\"\\\\n===== {_ahora()} INICIO {r.nombre} ({\' \'.join(r.comando(\'python\')[1:])}) =====\\\\n\\")\\n    r.log.flush()\\n    opciones = {}\\n    if os.name == \\"nt\\":\\n        opciones[\\"creationflags\\"] = subprocess.CREATE_NO_WINDOW | subprocess.CREATE_NEW_PROCESS_GROUP\\n    else:\\n        opciones[\\"start_new_session\\"] = True\\n    entorno = dict(os.environ, PYTHONUNBUFFERED=\\"1\\", PYTHONIOENCODING=\\"utf-8\\")\\n    r.proceso = subprocess.Popen(r.comando(python), cwd=RAIZ, stdout=r.log, stderr=subprocess.STDOUT,\\n                                 stdin=subprocess.DEVNULL, env=entorno, **opciones)\\n    r.inicio = time.monotonic()\\n    _msg(f\\"{r.nombre}: iniciada (pid {r.proceso.pid})\\")\\n\\n\\ndef _terminar(r: Rutina, motivo: str) -> None:\\n    p = r.proceso\\n    if p is None or p.poll() is not None:\\n        return\\n    _msg(f\\"{r.nombre}: deteniendo ({motivo})\\")\\n    try:\\n        if os.name == \\"nt\\":\\n            p.send_signal(signal.CTRL_BREAK_EVENT)\\n        else:\\n            os.killpg(p.pid, signal.SIGTERM)\\n        p.wait(timeout=15)\\n    except Exception:\\n        pass\\n    if p.poll() is None:\\n        p.kill()\\n        try:\\n            p.wait(timeout=10)\\n        except Exception:\\n            pass\\n\\n\\ndef revisar(r: Rutina) -> None:\\n    \\"\\"\\"Cierra la ejecución terminada o la detiene si superó su tiempo máximo.\\"\\"\\"\\n    if r.proceso is None:\\n        return\\n    if r.proceso.poll() is None:\\n        if time.monotonic() - r.inicio > r.timeout_minutos * 60:\\n            _terminar(r, f\\"superó {r.timeout_minutos} min\\")\\n        else:\\n            return\\n    codigo = r.proceso.returncode\\n    duracion = time.monotonic() - r.inicio\\n    estado = {0: \\"OK\\", 2: \\"PARCIAL\\"}.get(codigo, f\\"ERROR código {codigo}\\")\\n    r.ultima = f\\"{_ahora()} {estado} ({duracion / 60:.1f} min)\\"\\n    r.log.write(f\\"===== {_ahora()} FIN {r.nombre}: {estado} en {duracion:.0f}s =====\\\\n\\")\\n    r.log.close()\\n    r.proceso, r.log = None, None\\n    _msg(f\\"{r.nombre}: terminó {estado} en {duracion / 60:.1f} min\\")\\n\\n\\ndef bucle(rutinas: list[Rutina], python: str) -> int:\\n    candado = Candado(CANDADO)  # se mantiene tomado mientras viva esta variable\\n    activas = [r for r in rutinas if r.habilitada]\\n    if not activas:\\n        _msg(\\"No hay rutinas habilitadas. Nada que hacer.\\")\\n        return 0\\n    detener = threading.Event()\\n\\n    def senal(*_):\\n        detener.set()\\n\\n    signal.signal(signal.SIGINT, senal)\\n    if hasattr(signal, \\"SIGTERM\\"):\\n        signal.signal(signal.SIGTERM, senal)\\n    if hasattr(signal, \\"SIGBREAK\\"):\\n        signal.signal(signal.SIGBREAK, senal)\\n\\n    _msg(f\\"Lanzador iniciado en {RAIZ} con {python}\\")\\n    for r in activas:\\n        r.proxima = r.calcular_proxima(datetime.now())\\n        _msg(f\\"{r.nombre}: cada {str(r.cada_segundos) + chr(32) + \'s\' if r.cada_segundos else str(r.cada_minutos) + chr(32) + \'min\'} (desfase {r.desfase_minutos}) · próxima {r.proxima:%H:%M:%S}\\")\\n    for r in rutinas:\\n        if not r.habilitada:\\n            _msg(f\\"{r.nombre}: deshabilitada (RUTINA_{r.nombre.upper()}_HABILITADA)\\")\\n\\n    while not detener.is_set():\\n        ahora = datetime.now()\\n        for r in activas:\\n            revisar(r)\\n            if ahora >= r.proxima:\\n                if r.proceso is not None:\\n                    _msg(f\\"{r.nombre}: sigue corriendo; se salta el turno de las {r.proxima:%H:%M}\\")\\n                else:\\n                    try:\\n                        lanzar(r, python)\\n                    except Exception as exc:\\n                        _msg(f\\"{r.nombre}: no se pudo iniciar: {exc}\\")\\n                r.proxima = r.calcular_proxima(ahora)\\n        detener.wait(5)\\n\\n    _msg(\\"Deteniendo lanzador...\\")\\n    for r in activas:\\n        _terminar(r, \\"lanzador detenido\\")\\n        revisar(r)\\n    _msg(\\"Lanzador detenido.\\")\\n    candado.archivo.close()\\n    return 0\\n\\n\\ndef listar(rutinas: list[Rutina], python: str) -> int:\\n    print(f\\"Raíz: {RAIZ}\\\\nPython: {python}\\\\nLogs: {CARPETA_LOGS}\\\\n\\")\\n    for r in rutinas:\\n        estado = \\"HABILITADA\\" if r.habilitada else \\"deshabilitada\\"\\n        print(f\\"- {r.nombre} [{estado}] {r.descripcion}\\")\\n        print(f\\"    python -m {r.modulo} {\' \'.join(r.argumentos)}\\")\\n        print(f\\"    cada {str(r.cada_segundos) + \' s\' if r.cada_segundos else str(r.cada_minutos) + \' min\'}, desfase {r.desfase_minutos}, máximo {r.timeout_minutos} min, \\"\\n              f\\"próxima {r.calcular_proxima(datetime.now()):%Y-%m-%d %H:%M}\\")\\n        print(f\\"    log: {r.ruta_log}\\")\\n    return 0\\n\\n\\ndef ahora_una(rutinas: list[Rutina], nombre: str, python: str) -> int:\\n    r = next((x for x in rutinas if x.nombre.lower() == nombre.lower()), None)\\n    if r is None:\\n        print(f\\"No existe la rutina {nombre!r}. Use --listar.\\")\\n        return 1\\n    print(f\\"Ejecutando {r.nombre}: python -m {r.modulo} {\' \'.join(r.argumentos)}\\\\n\\", flush=True)\\n    try:\\n        return subprocess.run(r.comando(python), cwd=RAIZ, timeout=r.timeout_minutos * 60).returncode\\n    except subprocess.TimeoutExpired:\\n        print(f\\"\\\\nSuperó {r.timeout_minutos} min; detenida.\\")\\n        return 1\\n\\n\\ndef ciclo_estados_helix() -> int:\\n    \\"\\"\\"Publica una única lectura completa; nunca levanta otra API.\\"\\"\\"\\n    import json\\n    import tempfile\\n    from urllib.parse import urlsplit\\n    from urllib.request import Request, build_opener, ProxyHandler, HTTPRedirectHandler\\n    from urllib.error import HTTPError, URLError\\n\\n    class SinRedireccion(HTTPRedirectHandler):\\n        def redirect_request(self, req, fp, code, msg, headers, newurl):\\n            return None\\n\\n    configuracion = _leer_env()\\n    def valor(nombre, defecto=\\"\\"):\\n        return os.environ.get(nombre, configuracion.get(nombre, defecto)).strip()\\n\\n    carpeta = RAIZ / \\"backend\\" / \\"storage\\" / \\"estados_helix\\"\\n    carpeta.mkdir(parents=True, exist_ok=True)\\n    # Lock del SO compartido por --ahora y el scheduler; queda libre al morir.\\n    try:\\n        candado = Candado(carpeta / \\"consulta.lock\\")\\n    except SystemExit:\\n        _msg(\\"estados_helix: otra ejecución sigue activa; turno omitido\\")\\n        return 0\\n    temporal = None\\n    try:\\n        base = valor(\\"DATOS_SERVICE_URL\\")\\n        partes = urlsplit(base)\\n        if (partes.scheme not in (\\"http\\", \\"https\\") or not partes.hostname\\n                or partes.username is not None or partes.password is not None\\n                or partes.query or partes.fragment):\\n            raise ValueError(\\"DATOS_SERVICE_URL debe ser HTTP(S) sin credenciales, query ni fragmento\\")\\n        timeout = int(valor(\\"DATOS_SERVICE_TIMEOUT_SECONDS\\", \\"180\\"))\\n        if timeout < 0:\\n            raise ValueError(\\"DATOS_SERVICE_TIMEOUT_SECONDS debe ser >= 0\\")\\n        opener = build_opener(ProxyHandler({}), SinRedireccion())\\n        peticion = Request(base.rstrip(\\"/\\") + \\"/api/estados_helix/relaciones\\",\\n                           headers={\\"Accept\\": \\"application/json\\"})\\n        with opener.open(peticion, timeout=timeout or None) as respuesta:\\n            datos = json.load(respuesta)\\n        if (not isinstance(datos, dict) or datos.get(\\"ok\\") is not True\\n                or not isinstance(datos.get(\\"incidentes\\"), list)\\n                or not isinstance(datos.get(\\"resumen_relaciones\\"), dict)\\n                or not isinstance(datos.get(\\"fecha_corte\\"), str)):\\n            raise ValueError(\\"La API devolvió un contrato inesperado\\")\\n        datos.pop(\\"no_verificables\\", None)\\n        # Un único archivo vigente. Nunca borrar el anterior si falla Oracle/HTTP.\\n        with tempfile.NamedTemporaryFile(mode=\\"w\\", encoding=\\"utf-8\\", dir=carpeta,\\n                                         prefix=\\"actual-\\", suffix=\\".tmp\\", delete=False) as salida:\\n            temporal = Path(salida.name)\\n            json.dump(datos, salida, ensure_ascii=False, separators=(\\",\\", \\":\\"), allow_nan=False)\\n            salida.flush()\\n            os.fsync(salida.fileno())\\n        os.replace(temporal, carpeta / \\"actual.json\\")\\n        temporal = None\\n        _msg(\\"estados_helix: lectura publicada; INC=\\" + str(datos.get(\\"total\\", \\"?\\"))\\n             + \\"; TAS=\\" + str(datos[\\"resumen_relaciones\\"].get(\\"total_tareas\\", \\"?\\"))\\n             + \\"; corte=\\" + datos[\\"fecha_corte\\"])\\n        return 0\\n    except HTTPError as exc:\\n        _msg(\\"estados_helix: HTTP \\" + str(exc.code) + \\"; se conserva la lectura anterior\\")\\n        return 1\\n    except (URLError, TimeoutError, OSError):\\n        _msg(\\"estados_helix: fallo de conexión/escritura; se conserva la lectura anterior\\")\\n        return 1\\n    except (ValueError, TypeError):\\n        _msg(\\"estados_helix: configuración o respuesta inválida; se conserva la lectura anterior\\")\\n        return 1\\n    finally:\\n        if temporal is not None:\\n            temporal.unlink(missing_ok=True)\\n        candado.archivo.close()\\n\\n\\ndef ciclo_cmts_init() -> int:\\n    from microservicios.config import settings\\n    from microservicios.cmts.inits import inits_cmts as service\\n    if not settings.cmts_init_enabled:\\n        _msg(\\"cmts_init: CMTS_INIT_ENABLED=false; turno omitido\\")\\n        return 0\\n    claim = service.claim_cycle()\\n    if not claim[\\"created\\"]:\\n        _msg(\\"cmts_init: otra consulta sigue activa; turno omitido\\")\\n        return 0\\n    result = service.run_cycle(claim[\\"run_id\\"], claimed=True)\\n    failures = sum(not row[\\"ok\\"] for row in result[\\"rows\\"])\\n    _msg(f\\"cmts_init: {len(result[\'rows\'])} CMTS; {failures} fallidos\\")\\n    return 2 if failures else 0\\n\\n\\ndef ciclo_topologias() -> int:\\n    candado = Candado(CARPETA_LOGS / \\"topologias.lock\\")\\n    try:\\n        from microservicios.olt.topologias.service import materializar_aleatoria\\n        materializar_aleatoria()\\n        return 0\\n    finally:\\n        candado.archivo.close()\\n\\n\\ndef main() -> int:\\n    p = argparse.ArgumentParser(description=\\"Lanzador de rutinas de RKP\\")\\n    g = p.add_mutually_exclusive_group()\\n    g.add_argument(\\"--listar\\", action=\\"store_true\\", help=\\"Muestra las rutinas registradas\\")\\n    g.add_argument(\\"--ahora\\", metavar=\\"NOMBRE\\", help=\\"Ejecuta una rutina una vez, en primer plano\\")\\n    g.add_argument(\\"--ciclo-estados-helix\\", action=\\"store_true\\", help=argparse.SUPPRESS)\\n    g.add_argument(\\"--ciclo-cmts-init\\", action=\\"store_true\\", help=argparse.SUPPRESS)\\n    g.add_argument(\\"--ciclo-topologias\\", action=\\"store_true\\", help=argparse.SUPPRESS)\\n    a = p.parse_args()\\n    if a.ciclo_cmts_init:\\n        return ciclo_cmts_init()\\n    if a.ciclo_topologias:\\n        return ciclo_topologias()\\n    if a.ciclo_estados_helix:\\n        return ciclo_estados_helix()\\n    env = _leer_env()\\n    # Compatibilidad con las variables existentes; RUTINA_* tiene prioridad.\\n    for key, value in os.environ.items():\\n        if key.startswith(\\"RUTINA_\\"):\\n            env[key] = value\\n    def configuracion(clave, defecto):\\n        return os.environ.get(clave, env.get(clave, defecto))\\n    env.setdefault(\\"RUTINA_CMTS_INIT_HABILITADA\\", configuracion(\\"CMTS_INIT_ENABLED\\", \\"false\\"))\\n    if \\"RUTINA_CMTS_INIT_CADA_MINUTOS\\" not in env and \\"RUTINA_CMTS_INIT_CADA_SEGUNDOS\\" not in env:\\n        env[\\"RUTINA_CMTS_INIT_CADA_SEGUNDOS\\"] = str(max(60, int(configuracion(\\"CMTS_INIT_INTERVAL_SECONDS\\", \\"900\\"))))\\n    env.setdefault(\\"RUTINA_TOPOLOGIAS_HABILITADA\\", \\"true\\" if configuracion(\\"TOPOLOGIAS_AUTO\\", \\"0\\") == \\"1\\" else \\"false\\")\\n    python = env.get(\\"RUTINAS_PYTHON\\", \\"\\").strip() or sys.executable\\n    rutinas = cargar_rutinas(env)\\n    if a.listar:\\n        return listar(rutinas, python)\\n    if a.ahora:\\n        return ahora_una(rutinas, a.ahora, python)\\n    return bucle(rutinas, python)\\n\\n\\nif __name__ == \\"__main__\\":\\n    sys.exit(main())\\n\\n"}, "microservicios/app.py": {"sha256": "17c2fcd4b6d31eb75fb0ee8e7e89de9ad547d9d3bbb6d0de9ba2e90be13e1721", "content": "\\"\\"\\"Aplicacion FastAPI principal de Backend Datos.\\"\\"\\"\\n\\nimport asyncio\\nimport os\\nfrom contextlib import asynccontextmanager\\n\\nfrom fastapi import FastAPI, HTTPException, Request\\nfrom fastapi.exceptions import RequestValidationError\\nfrom fastapi.responses import JSONResponse\\n\\nfrom microservicios.config import settings\\n\\nfrom microservicios.estados_helix.router import (\\n    router as estados_helix_router,\\n)\\n\\nfrom microservicios.cmts.dashboard_hfc.router_helix import (\\n    router as hfc_helix_router,\\n)\\nfrom microservicios.cmts.inits.router import (\\n    router as cmts_inits_router,\\n    stop_scheduler as stop_cmts_inits_scheduler,\\n)\\nfrom microservicios.cmts.intermitencias.router import (\\n    router as cmts_intermitencias_router,\\n)\\nfrom microservicios.cmts.puertos_docsis.router import (\\n    router as cmts_puertos_docsis_router,\\n)\\nfrom microservicios.cmts.puertos_duplicados.router import (\\n    router as cmts_puertos_duplicados_router,\\n)\\nfrom microservicios.cmts.saturacion.router import (\\n    router as cmts_saturacion_router,\\n)\\n\\nfrom microservicios.olt.caidas.router import router as caidas_router\\nfrom microservicios.olt.casos_helix import service as casos_helix_service\\nfrom microservicios.olt.casos_helix.router import router as casos_helix_router\\nfrom microservicios.olt.casos_helix.worker import (\\n    get_worker as get_helix_worker,\\n    start_worker as start_helix_worker,\\n    stop_worker as stop_helix_worker,\\n)\\nfrom microservicios.olt.correlacion.router import router as correlacion_router\\nfrom microservicios.olt.crc.router import router as crc_router\\nfrom microservicios.olt.perdida_latencia.router import (\\n    router as perdida_latencia_router,\\n)\\nfrom microservicios.olt.recursos_zte.router import router as recursos_zte_router\\nfrom microservicios.olt.saturacion.router import router as saturacion_router\\nfrom microservicios.olt.temperatura.router import router as temperatura_router\\nfrom microservicios.olt.topologias import service as topologias_service\\nfrom microservicios.olt.topologias.router import router as topologias_router\\n\\n\\n@asynccontextmanager\\nasync def lifespan(_app: FastAPI):\\n\\n    start_helix_worker(\\n        casos_helix_service.consultar_olt,\\n        ttl_seconds=settings.oracle_helix_cache_seconds,\\n    )\\n\\n    try:\\n        yield\\n    finally:\\n        await stop_cmts_inits_scheduler()\\n        stop_helix_worker()\\n        casos_helix_service.close_oracle_pool()  # RKP_HELIX_OPT_V1\\n\\n\\n\\napp = FastAPI(\\n    title=\\"Backend Datos API\\",\\n    version=\\"1.0.0\\",\\n    lifespan=lifespan,\\n)\\n\\n\\n@app.exception_handler(Exception)\\nasync def error_no_controlado(\\n    _request: Request,\\n    _exc: Exception,\\n) -> JSONResponse:\\n    return JSONResponse(\\n        status_code=500,\\n        content={\\n            \\"ok\\": False,\\n            \\"error\\": \\"Error interno del servicio\\",\\n        },\\n    )\\n\\n\\n@app.exception_handler(HTTPException)\\nasync def error_http(\\n    _request: Request,\\n    exc: HTTPException,\\n) -> JSONResponse:\\n    return JSONResponse(\\n        status_code=exc.status_code,\\n        content={\\n            \\"ok\\": False,\\n            \\"error\\": str(exc.detail),\\n        },\\n        headers=exc.headers,\\n    )\\n\\n\\n@app.exception_handler(RequestValidationError)\\nasync def error_validacion(\\n    _request: Request,\\n    _exc: RequestValidationError,\\n) -> JSONResponse:\\n    return JSONResponse(\\n        status_code=422,\\n        content={\\n            \\"ok\\": False,\\n            \\"error\\": \\"Parametros invalidos\\",\\n        },\\n    )\\n\\n\\n@app.get(\\"/health\\")\\ndef health() -> dict[str, object]:\\n    return {\\n        \\"ok\\": True,\\n        \\"service\\": \\"Backend Datos API\\",\\n    }\\n\\n\\n# RKP_RECUPERACION_V1:\\n# Salud del proceso/trabajador; no depende de disponibilidad DB.\\n@app.get(\\"/health/recovery\\")\\ndef recovery_health() -> JSONResponse:\\n    budget = settings.oracle_helix_query_budget_seconds\\n\\n    # Sin presupuesto positivo no se adivina un limite\\n    # para consultas legitimas.\\n    limit = float(budget) + 60 if budget > 0 else float(\\"inf\\")\\n\\n    worker = get_helix_worker()\\n    state = (\\n        worker.recovery_status(limit)\\n        if worker is not None\\n        else {\\n            \\"ok\\": False,\\n            \\"reason\\": \\"worker_missing\\",\\n        }\\n    )\\n\\n    body = {\\n        \\"ok\\": bool(state[\\"ok\\"]),\\n        \\"service\\": \\"Backend Datos API\\",\\n        \\"helix\\": state,\\n    }\\n\\n    return JSONResponse(\\n        status_code=200 if body[\\"ok\\"] else 503,\\n        content=body,\\n    )\\n\\n\\n# OLT\\napp.include_router(saturacion_router, prefix=\\"/api/olt\\")\\napp.include_router(caidas_router, prefix=\\"/api/olt\\")\\napp.include_router(casos_helix_router, prefix=\\"/api/olt\\")\\napp.include_router(crc_router, prefix=\\"/api/olt\\")\\napp.include_router(correlacion_router, prefix=\\"/api/olt\\")\\napp.include_router(temperatura_router, prefix=\\"/api/olt\\")\\napp.include_router(topologias_router, prefix=\\"/api/olt\\")\\napp.include_router(perdida_latencia_router, prefix=\\"/api/olt\\")\\napp.include_router(recursos_zte_router, prefix=\\"/api/olt\\")\\n\\n# CMTS\\napp.include_router(cmts_saturacion_router, prefix=\\"/api/cmts\\")\\napp.include_router(cmts_puertos_docsis_router, prefix=\\"/api/cmts\\")\\napp.include_router(cmts_intermitencias_router, prefix=\\"/api/cmts\\")\\napp.include_router(cmts_puertos_duplicados_router, prefix=\\"/api/cmts\\")\\napp.include_router(cmts_inits_router, prefix=\\"/api/cmts\\")\\n\\n# Estados Helix\\napp.include_router(estados_helix_router)\\n\\n# Casos abiertos Helix por nodo HFC\\napp.include_router(hfc_helix_router, prefix=\\"/api/hfc\\")\\n"}, "microservicios/apis_separadas.py": {"sha256": "5af6d56a5ce86411a837950d30e714dc64002c1a8c4106402ae8fdb46268a87d", "content": "\\"\\"\\"APIs por carpeta y gateway compatible con las rutas públicas existentes.\\"\\"\\"\\nfrom __future__ import annotations\\n\\nimport ast\\nimport asyncio\\nimport importlib\\nimport logging\\nimport os\\nimport zlib\\nfrom contextlib import asynccontextmanager, suppress\\nfrom dataclasses import dataclass\\nfrom functools import lru_cache\\nfrom pathlib import Path\\n\\nfrom fastapi import Request\\n\\nfrom microservicios.entorno import ROOT, env\\n\\nBASE = ROOT / \'microservicios\'\\nKNOWN = {\\n    name: 18100 + index for index, name in enumerate((\\n        \'cmts/inits\', \'cmts/intermitencias\', \'cmts/puertos_docsis\',\\n        \'cmts/puertos_duplicados\', \'cmts/saturacion\', \'estados_helix\',\\n        \'olt/caidas\', \'olt/casos_helix\', \'olt/correlacion\', \'olt/crc\',\\n        \'olt/perdida_latencia\', \'olt/recursos_zte\', \'olt/saturacion\',\\n        \'olt/temperatura\', \'olt/topologias\',\\n    ))\\n}\\nKNOWN[\'cmts/hfc_casos_helix\'] = 31404\\nMETHODS = {\'get\', \'post\', \'put\', \'patch\', \'delete\', \'head\', \'options\'}\\n\\n@dataclass(frozen=True)\\nclass Service:\\n    name: str\\n    module: str\\n    port: int\\n    mount: str\\n    routes: tuple\\n\\n    @property\\n    def key(self):\\n        return \'SVC_\' + self.name.replace(\'/\', \'_\').upper()\\n\\n    @property\\n    def health_name(self):\\n        return \'RKP API: \' + self.name\\n\\n\\ndef read_routes(path, mount):\\n    \\"\\"\\"Descubre rutas sin importar todos los módulos en cada proceso.\\"\\"\\"\\n    tree = ast.parse(path.read_text(encoding=\'utf-8-sig\'))\\n    prefix = \'\'\\n    found = False\\n    for node in tree.body:\\n        if isinstance(node, ast.Assign) and any(isinstance(t, ast.Name) and t.id == \'router\' for t in node.targets):\\n            if isinstance(node.value, ast.Call):\\n                found = True\\n                for kw in node.value.keywords:\\n                    if kw.arg == \'prefix\':\\n                        prefix = ast.literal_eval(kw.value)\\n    if not found:\\n        return ()\\n    routes = []\\n    for node in tree.body:\\n        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):\\n            continue\\n        for dec in node.decorator_list:\\n            if not (isinstance(dec, ast.Call) and isinstance(dec.func, ast.Attribute)\\n                    and isinstance(dec.func.value, ast.Name) and dec.func.value.id == \'router\'):\\n                continue\\n            if dec.func.attr not in METHODS:\\n                raise RuntimeError(f\'{path}: decorador {dec.func.attr} requiere configurar su publicación\')\\n            value = dec.args[0] if dec.args else next(k.value for k in dec.keywords if k.arg == \'path\')\\n            route = mount + prefix + ast.literal_eval(value)\\n            routes.append((route, dec.func.attr.upper()))\\n    return tuple(routes)\\n\\n\\n@lru_cache(maxsize=1)\\ndef catalog():\\n    services = []\\n    ports, routes = {}, {}\\n    for path in sorted(BASE.rglob(\'router.py\')):\\n        relative = path.parent.relative_to(BASE)\\n        if any(part.startswith(\'.\') or part in {\'__pycache__\', \'venv\', \'.venv\'} for part in relative.parts):\\n            continue\\n        name = relative.as_posix()\\n\\n        if name == \'cmts/hfc_casos_helix\':\\n            mount = \'\'\\n        else:\\n            mount = (\\n                \'/api/\' + relative.parts[0]\\n                if relative.parts[0] in {\'olt\', \'cmts\'}\\n                else \'\'\\n            )\\n        declared = read_routes(path, mount)\\n        if not declared:\\n            continue\\n        slug = name.replace(\'/\', \'_\').upper()\\n        default = KNOWN.get(name, 20000 + zlib.crc32(name.encode()) % 20000)\\n        number = int(env(\'RKP_API_\' + slug + \'_PORT\', str(default)))\\n        if not 1 <= number <= 65535 or number in ports:\\n            raise RuntimeError(f\'Puerto independiente inválido/duplicado: {name}={number}\')\\n        for item in declared:\\n            if item in routes:\\n                raise RuntimeError(f\'Ruta duplicada: {item} en {name} y {routes[item]}\')\\n            routes[item] = name\\n        ports[number] = name\\n        services.append(Service(name, \'microservicios.\' + \'.\'.join(relative.parts) + \'.router\', number, mount, declared))\\n    if not services:\\n        raise RuntimeError(\'No se encontraron carpetas API con router.py\')\\n    return tuple(services)\\n\\n\\ndef install_errors(app):\\n    from fastapi import HTTPException\\n    from fastapi.exceptions import RequestValidationError\\n    from fastapi.responses import JSONResponse\\n\\n    @app.exception_handler(HTTPException)\\n    async def http_error(request, exc):\\n        return JSONResponse(status_code=exc.status_code, content={\'ok\': False, \'error\': str(exc.detail)}, headers=exc.headers)\\n\\n    @app.exception_handler(RequestValidationError)\\n    async def validation_error(request, exc):\\n        return JSONResponse(status_code=422, content={\'ok\': False, \'error\': \'Parametros invalidos\'})\\n\\n    @app.exception_handler(Exception)\\n    async def unexpected_error(request, exc):\\n        logging.getLogger(__name__).error(\'Error en %s\', request.url.path, exc_info=exc)\\n        return JSONResponse(status_code=500, content={\'ok\': False, \'error\': \'Error interno del servicio\'})\\n\\n\\ndef create_service():\\n    from fastapi import FastAPI\\n    name = os.environ[\'RKP_SERVICE_ID\']\\n    spec = next((s for s in catalog() if s.name == name), None)\\n    if spec is None:\\n        raise RuntimeError(\'API independiente no registrada: \' + name)\\n    module = importlib.import_module(spec.module)\\n\\n    @asynccontextmanager\\n    async def lifespan(app):\\n        helix = None\\n        try:\\n            if name == \'olt/casos_helix\':\\n                from microservicios.config import settings\\n                from microservicios.olt.casos_helix import service, worker\\n                helix = (service, worker)\\n                worker.start_worker(service.consultar_olt, ttl_seconds=settings.oracle_helix_cache_seconds)\\n            yield\\n        finally:\\n            if name == \'cmts/inits\':\\n                await module.stop_scheduler()\\n            if helix:\\n                helix[1].stop_worker()\\n                helix[0].close_oracle_pool()\\n\\n    app = FastAPI(title=spec.health_name, lifespan=lifespan)\\n    install_errors(app)\\n\\n    @app.get(\'/health\')\\n    async def health():\\n        return {\'ok\': True, \'service\': spec.health_name, \'mode\': \'independent\', \'pid\': os.getpid()}\\n\\n    app.include_router(module.router, prefix=spec.mount)\\n    return app\\n\\n\\n# Encabezados de transporte no deben atravesar el proxy.\\nHOP_HEADERS = {\'connection\', \'keep-alive\', \'proxy-authenticate\', \'proxy-authorization\',\\n               \'te\', \'trailer\', \'transfer-encoding\', \'upgrade\'}\\n\\n\\ndef open_upstream(service, request, body):\\n    import requests\\n    session = requests.Session()\\n    session.trust_env = False\\n    forbidden = HOP_HEADERS | {v.strip().lower() for v in request.headers.get(\'connection\', \'\').split(\',\')}\\n    headers = {k: v for k, v in request.headers.items() if k.lower() not in forbidden}\\n    timeout = float(env(\'RKP_GATEWAY_READ_TIMEOUT_SECONDS\', \'0\'))\\n    if timeout < 0:\\n        raise ValueError(\'RKP_GATEWAY_READ_TIMEOUT_SECONDS no puede ser negativo\')\\n    target = f\'http://127.0.0.1:{service.port}\' + request.scope.get(\'raw_path\', request.url.path.encode()).decode(\'ascii\')\\n    if request.url.query:\\n        target += \'?\' + request.url.query\\n    try:\\n        response = session.request(request.method, target, headers=headers, data=body,\\n                                   timeout=(5, timeout or None), stream=True, allow_redirects=False)\\n        return session, response\\n    except BaseException:\\n        session.close()\\n        raise\\n\\n\\ndef create_gateway():\\n    from fastapi import FastAPI, Request\\n    from fastapi.responses import JSONResponse, StreamingResponse\\n    from starlette.background import BackgroundTask\\n    specs = catalog()\\n    app = FastAPI(title=\'Backend Datos API\', version=\'2.0.0\')\\n    install_errors(app)\\n\\n    @app.get(\'/health\')\\n    @app.get(\'/health/recovery\')\\n    async def health():\\n        return {\'ok\': True, \'service\': \'Backend Datos API\', \'mode\': \'gateway\', \'pid\': os.getpid()}\\n\\n    @app.get(\'/servicios\')\\n    async def services():\\n        return {\'ok\': True, \'services\': [\\n            {\'name\': s.name, \'port\': s.port, \'health\': f\'http://127.0.0.1:{s.port}/health\',\\n             \'routes\': [p for p, _ in s.routes]} for s in specs\\n        ]}\\n\\n    async def proxy(request: Request):\\n        import requests\\n        service = request.scope[\'route\'].rkp_service\\n        body = await request.body()\\n        try:\\n            session, response = await asyncio.to_thread(open_upstream, service, request, body)\\n        except requests.Timeout:\\n            return JSONResponse(status_code=504, content={\'ok\': False, \'error\': \'Tiempo de espera del servicio agotado\', \'service\': service.name})\\n        except requests.RequestException:\\n            return JSONResponse(status_code=502, content={\'ok\': False, \'error\': \'API independiente no disponible\', \'service\': service.name})\\n\\n        def close():\\n            response.close()\\n            session.close()\\n\\n        async def chunks():\\n            try:\\n                while True:\\n                    block = await asyncio.to_thread(response.raw.read, 65536, decode_content=False)\\n                    if not block:\\n                        break\\n                    yield block\\n            finally:\\n                close()\\n        forbidden = HOP_HEADERS | {v.strip().lower() for v in response.headers.get(\'Connection\', \'\').split(\',\')}\\n        result = StreamingResponse(chunks(), status_code=response.status_code, background=BackgroundTask(close))\\n        # Conserva Content-Type, descargas, compresión y encabezados repetidos.\\n        result.raw_headers = [\\n            (key.lower().encode(\'latin-1\'), value.encode(\'latin-1\'))\\n            for key in response.raw.headers.keys() if key.lower() not in forbidden\\n            for value in response.raw.headers.getlist(key)\\n        ]\\n        return result\\n\\n    # El orden específico antes de los parámetros mantiene el enrutamiento.\\n    entries = sorted(((s, path, method) for s in specs for path, method in s.routes),\\n                     key=lambda row: (row[1].count(\'{\'), -len(row[1]), row[1]))\\n    for service, path, method in entries:\\n        app.add_api_route(path, proxy, methods=[method], name=service.name + \':\' + method + \':\' + path)\\n        app.routes[-1].rkp_service = service\\n    return app\\n"}, "microservicios/cmts/inits/router.py": {"sha256": "694f5a8c096e06ae89112a24f76d6aa329965679eaaed6afaa9f2dc0dc67a844", "content": "\\"\\"\\"API del monitoreo INIT; GET sólo consulta CSV ya publicados.\\"\\"\\"\\nimport asyncio\\nimport csv\\nimport io\\nfrom contextlib import suppress\\n\\nfrom fastapi import APIRouter, HTTPException, Query, Response\\nfrom fastapi.responses import StreamingResponse, FileResponse\\nfrom starlette.background import BackgroundTask\\nfrom pathlib import Path\\nfrom tempfile import NamedTemporaryFile\\nfrom datetime import datetime, timedelta, timezone\\nfrom microservicios.cmts.inits.export_excel import write_excel, select_rows, MIME\\n\\nfrom microservicios.config import settings\\nfrom microservicios.cmts.inits import inits_cmts as service\\n\\nrouter = APIRouter(tags=[\\"CMTS - Monitoreo INIT\\"])\\n_cycle_task: asyncio.Task | None = None\\n_scheduler_task: asyncio.Task | None = None\\n\\n\\ndef _summary(rows: list[dict]) -> dict:\\n    valid = [row for row in rows if row[\\"ok\\"] and row[\\"total_init\\"] is not None]\\n    return {\\"total_cmts\\": len(rows), \\"exitosas\\": len(valid), \\"fallidas\\": len(rows) - len(valid),\\n            \\"total_init\\": sum(row[\\"total_init\\"] for row in valid), \\"cobertura\\": len(valid) / len(rows) if rows else 0}\\n\\n\\ndef _with_delta(rows: list[dict]) -> list[dict]:\\n    previous = {}\\n    try:\\n        with (service.data_dir() / \\"historico.csv\\").open(newline=\\"\\", encoding=\\"utf-8-sig\\") as f:\\n            for old in csv.DictReader(f):\\n                if old.get(\\"ok\\", \\"\\").lower() == \\"true\\" and old.get(\\"total_init\\") not in (None, \\"\\") and (not rows or old.get(\\"run_id\\") != rows[0].get(\\"run_id\\")):\\n                    previous[old[\\"cmts\\"]] = old\\n    except OSError:\\n        pass\\n    output = []\\n    for row in rows:\\n        old = previous.get(row[\\"cmts\\"])\\n        delta = row[\\"total_init\\"] - int(old[\\"total_init\\"]) if row[\\"ok\\"] and row[\\"total_init\\"] is not None and old else None\\n        output.append({**row, \\"variacion\\": delta, \\"comparado_con\\": old.get(\\"fecha\\") if delta is not None else None})\\n    return output\\n\\n\\nasync def _run_cycle(run_id: str | None = None, claimed: bool = False) -> None:\\n    global _cycle_task\\n    try:\\n        await asyncio.to_thread(service.run_cycle, run_id, claimed=claimed)\\n    except Exception as exc:\\n        print(f\\"[CMTS INIT] Ciclo {run_id or \'manual\'} terminó con error: {type(exc).__name__}\\")\\n    finally:\\n        _cycle_task = None\\n\\n\\nasync def _run_probe(run_id: str, cmts: str) -> None:\\n    global _cycle_task\\n    try:\\n        await asyncio.to_thread(service.run_probe, cmts, run_id, claimed=True)\\n    except Exception as exc:\\n        print(f\\"[CMTS INIT] Prueba {cmts} terminó con error: {type(exc).__name__}\\")\\n    finally:\\n        _cycle_task = None\\n\\n\\nasync def start_scheduler() -> None:\\n    \\"\\"\\"La programación automática pertenece a iniciar_rutinas.py.\\"\\"\\"\\n    return None\\n\\n\\nasync def stop_scheduler() -> None:\\n    global _scheduler_task, _cycle_task\\n    if _scheduler_task:\\n        _scheduler_task.cancel()\\n        with suppress(asyncio.CancelledError): await _scheduler_task\\n        _scheduler_task = None\\n    if _cycle_task and not _cycle_task.done():\\n        # Do not cancel an in-flight SSH thread; individual connections are bounded at 90 s.\\n        with suppress(Exception, asyncio.TimeoutError):\\n            await asyncio.wait_for(asyncio.shield(_cycle_task), timeout=95)\\n    _cycle_task = None\\n\\n\\n@router.get(\\"/inits/actual\\")\\ndef actual() -> dict:\\n    try:\\n        rows = service.actual()\\n        return {\\"ok\\": True, \\"data\\": {\\"items\\": _with_delta(rows), \\"resumen\\": _summary(rows),\\n                \\"run_id\\": rows[0][\\"run_id\\"] if rows else None, \\"fecha\\": max((r[\\"fecha\\"] for r in rows), default=None)}}\\n    except (OSError, ValueError) as exc:\\n        raise HTTPException(503, str(exc)) from exc\\n\\n\\n@router.get(\\"/inits/estado\\")\\ndef estado() -> dict:\\n    data = service.status(); data[\\"progreso\\"] = service.get_progress()\\n    return {\\"ok\\": True, \\"data\\": data}\\n\\n\\n@router.post(\\"/inits/actualizar\\", status_code=202)\\nasync def actualizar(response: Response) -> dict:\\n    global _cycle_task\\n    if not settings.cmts_init_enabled:\\n        raise HTTPException(503, \\"Monitoreo INIT deshabilitado\\")\\n    if not settings.cmts_user or not settings.cmts_password:\\n        raise HTTPException(503, \\"Configura CMTS_USER y CMTS_PASSWORD\\")\\n    run_id = None\\n    reused = False\\n    if _cycle_task is None or _cycle_task.done():\\n        try:\\n            claim = service.claim_cycle()\\n        except RuntimeError as exc:\\n            raise HTTPException(409, str(exc)) from exc\\n        if not claim[\\"created\\"] and claim.get(\\"alcance\\") != \\"global\\":\\n            raise HTTPException(409, \\"Hay una prueba individual en curso\\")\\n        if claim[\\"created\\"]:\\n            _cycle_task = asyncio.create_task(_run_cycle(claim[\\"run_id\\"], True))\\n        else:\\n            run_id = claim[\\"run_id\\"]\\n            reused = True\\n            response.headers[\\"Retry-After\\"] = \\"5\\"\\n            return {\\"ok\\": True, \\"estado\\": \\"procesando\\", \\"run_id\\": run_id, \\"reutilizado\\": True}\\n        run_id = claim[\\"run_id\\"]\\n    else:\\n        active = service.status()\\n        if active.get(\\"alcance_activo\\") != \\"global\\":\\n            raise HTTPException(409, \\"Hay una prueba individual en curso\\")\\n        run_id = active.get(\\"run_id\\")\\n        reused = True\\n    response.headers[\\"Retry-After\\"] = \\"5\\"\\n    return {\\"ok\\": True, \\"estado\\": \\"procesando\\", \\"run_id\\": run_id, \\"reutilizado\\": reused}\\n\\n\\n@router.post(\\"/inits/probar\\", status_code=202)\\nasync def probar(response: Response, cmts: str = Query(..., min_length=1, max_length=160)) -> dict:\\n    global _cycle_task\\n    if not settings.cmts_init_enabled:\\n        raise HTTPException(503, \\"Monitoreo INIT deshabilitado\\")\\n    if not settings.cmts_user or not settings.cmts_password:\\n        raise HTTPException(503, \\"Configura CMTS_USER y CMTS_PASSWORD\\")\\n    try:\\n        items = service.inventory()\\n    except (OSError, ValueError) as exc:\\n        raise HTTPException(503, str(exc)) from exc\\n    if not any(item[\\"cmts\\"].casefold() == cmts.casefold() or item[\\"ip\\"] == cmts for item in items):\\n        raise HTTPException(404, \\"CMTS no encontrado en el inventario\\")\\n    run_id = None\\n    reused = False\\n    if _cycle_task is None or _cycle_task.done():\\n        try:\\n            claim = service.claim_cycle(\\"equipo\\", cmts)\\n        except RuntimeError as exc:\\n            raise HTTPException(409, str(exc)) from exc\\n        if not claim[\\"created\\"]:\\n            if claim.get(\\"alcance\\") != \\"equipo\\" or claim.get(\\"cmts\\", \\"\\").casefold() != cmts.casefold():\\n                raise HTTPException(409, \\"Hay otro ciclo CMTS en curso\\")\\n            run_id, reused = claim[\\"run_id\\"], True\\n        else:\\n            run_id = claim[\\"run_id\\"]\\n            _cycle_task = asyncio.create_task(_run_probe(run_id, cmts))\\n    else:\\n        active = service.status()\\n        if active.get(\\"alcance_activo\\") != \\"equipo\\" or active.get(\\"cmts_activo\\", \\"\\").casefold() != cmts.casefold():\\n            raise HTTPException(409, \\"Hay otro ciclo CMTS en curso\\")\\n        run_id, reused = active.get(\\"run_id\\"), True\\n    response.headers[\\"Retry-After\\"] = \\"5\\"\\n    return {\\"ok\\": True, \\"estado\\": \\"procesando\\", \\"run_id\\": run_id, \\"reutilizado\\": reused, \\"alcance\\": \\"equipo\\"}\\n\\n\\n@router.get(\\"/inits/historico\\")\\ndef historico(cmts: str = \\"\\", desde: str = \\"\\", hasta: str = \\"\\", limit: int = Query(100, ge=1, le=1000), offset: int = Query(0, ge=0)) -> dict:\\n    try: return {\\"ok\\": True, \\"data\\": service.history(cmts=cmts, desde=desde, hasta=hasta, limit=limit, offset=offset)}\\n    except FileNotFoundError: return {\\"ok\\": True, \\"data\\": {\\"items\\": [], \\"total\\": 0, \\"limit\\": limit, \\"offset\\": offset}}\\n    except (OSError, ValueError) as exc: raise HTTPException(503, str(exc)) from exc\\n\\n\\n@router.get(\\"/inits/tendencia\\")\\ndef tendencia(cmts: str, limit: int = Query(200, ge=2, le=1000)) -> dict:\\n    try: return {\\"ok\\": True, \\"data\\": service.trend(cmts, limit)}\\n    except FileNotFoundError: return {\\"ok\\": True, \\"data\\": []}\\n    except (OSError, ValueError) as exc: raise HTTPException(503, str(exc)) from exc\\n\\n\\ndef _safe_cell(value: str, numeric: bool) -> str:\\n    if not numeric and value.startswith((\\"=\\", \\"+\\", \\"-\\", \\"@\\", \\"\\\\t\\", \\"\\\\r\\")): return \\"\'\\" + value\\n    return value\\n\\n\\n@router.get(\\"/inits/exportar\\")\\ndef exportar(cmts: str = \\"\\", desde: str = \\"\\", hasta: str = \\"\\"):\\n    \\"\\"\\"CSV legible del histórico; nunca altera los CSV internos.\\"\\"\\"\\n    def stream():\\n        buffer = io.StringIO(newline=\\"\\")\\n        writer = csv.writer(buffer, delimiter=\\";\\")\\n        writer.writerow([\\"Fecha Colombia\\", \\"CMTS\\", \\"IP\\", \\"Total INIT\\", \\"Gravedad\\", \\"Consulta\\", \\"Detalle\\", \\"Alcance\\", \\"Ciclo\\"])\\n        yield \\"\\\\ufeffsep=;\\\\r\\\\n\\" + buffer.getvalue()\\n        buffer.seek(0); buffer.truncate(0)\\n        for row in service.export_rows(cmts, desde, hasta):\\n            stamp = datetime.fromisoformat(row[\\"fecha\\"].replace(\\"Z\\", \\"+00:00\\"))\\n            if stamp.tzinfo is None: stamp = stamp.replace(tzinfo=timezone.utc)\\n            fecha = stamp.astimezone(timezone(timedelta(hours=-5))).strftime(\\"%Y-%m-%d %H:%M:%S\\")\\n            valid = str(row.get(\\"ok\\", \\"\\")).lower() == \\"true\\" and row.get(\\"total_init\\") not in (None, \\"\\")\\n            values = [fecha, row[\\"cmts\\"], row[\\"ip\\"], row[\\"total_init\\"] if valid else \\"\\", row[\\"estado\\"], \\"ÉXITO\\" if valid else \\"FALLÓ\\", str(row.get(\\"error\\") or \\"\\").replace(\\"\\\\r\\", \\" \\").replace(\\"\\\\n\\", \\" \\"), row[\\"alcance\\"], row[\\"run_id\\"]]\\n            writer.writerow([_safe_cell(str(v), i == 3) for i, v in enumerate(values)])\\n            yield buffer.getvalue(); buffer.seek(0); buffer.truncate(0)\\n    return StreamingResponse(stream(), media_type=\\"text/csv; charset=utf-8\\", headers={\\"Content-Disposition\\": \\"attachment; filename=cmts-init-historico.csv\\"})\\n\\n\\ndef _history_excel_rows(busqueda: str, estado: str, start: datetime, end: datetime):\\n    \\"\\"\\"Streaming; conserva una última lectura válida por CMTS como referencia.\\"\\"\\"\\n    previous = {}\\n    for raw in service.export_rows(\\"\\", \\"\\", end.isoformat()):\\n        row = service.normalize(raw)\\n        stamp = datetime.fromisoformat(row[\\"fecha\\"].replace(\\"Z\\", \\"+00:00\\"))\\n        if stamp.tzinfo is None: stamp = stamp.replace(tzinfo=timezone.utc)\\n        valid = row[\\"ok\\"] and row[\\"total_init\\"] is not None\\n        old = previous.get(row[\\"cmts\\"])\\n        delta = row[\\"total_init\\"] - old if valid and old is not None else None\\n        if valid: previous[row[\\"cmts\\"]] = row[\\"total_init\\"]\\n        if start <= stamp <= end:\\n            row[\\"variacion\\"] = delta\\n            yield from select_rows([row], busqueda, estado)\\n\\n\\n@router.get(\\"/inits/exportar-excel\\")\\ndef exportar_excel(busqueda: str = \\"\\", estado: str = \\"\\", ordenar: str = \\"total_init\\", direccion: int = -1, alcance: str = Query(\\"actual\\", pattern=\\"^(actual|historico5d)$\\")):\\n    history = alcance == \\"historico5d\\"\\n    now = datetime.now(timezone.utc)\\n    start = now - timedelta(days=5)\\n    rows = _history_excel_rows(busqueda, estado, start, now) if history else select_rows(_with_delta(service.actual()), busqueda, estado, ordenar, direccion)\\n    with NamedTemporaryFile(suffix=\\".xlsx\\", delete=False) as f:\\n        path = Path(f.name)\\n    try:\\n        write_excel(path, rows, search=busqueda, estado=estado, include_chart=not history, historical=history, period=(start, now) if history else None)\\n    except Exception:\\n        path.unlink(missing_ok=True)\\n        raise\\n    filename = \\"cmts-init-historico-5-dias.xlsx\\" if history else \\"cmts-init-actual.xlsx\\"\\n    return FileResponse(path, media_type=MIME, filename=filename, background=BackgroundTask(path.unlink, missing_ok=True))\\n"}}')
def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--raiz', type=Path, default=Path(__file__).resolve().parent)
    p.add_argument('--aplicar', action='store_true')
    a=p.parse_args(); root=a.raiz.resolve(); pending=[]
    for relative, data in PAYLOAD.items():
        path=root/relative
        original=path.read_bytes()
        text=original.decode('utf-8-sig').replace('\r\n','\n')
        if text == data['content']:
            print('YA APLICADO:',relative); continue
        if hashlib.sha256(text.encode()).hexdigest()!=data['sha256']:
            raise SystemExit('ABORTADO: versión local distinta: '+str(path)+'; no se modificó ningún archivo.')
        ast.parse(data['content'], filename=relative)
        pending.append((path,relative,data['content']))
    if not pending: return
    if not a.aplicar:
        print('Verificación OK. Archivos a cambiar:',len(pending))
        print('Detén las APIs y el lanzador; repite con --aplicar.'); return
    backup=root/'backups'/('rutinas_'+datetime.now().strftime('%Y%m%d_%H%M%S_%f'))
    # Respaldar TODOS antes de sobrescribir el primero.
    for path,relative,_ in pending:
        dest=backup/relative; dest.parent.mkdir(parents=True,exist_ok=True)
        shutil.copy2(path,dest); print('RESPALDO:',dest)
    try:
        for path,relative,text in pending:
            temp=path.with_name(path.name+'.rutinas.tmp')
            temp.write_text(text,encoding='utf-8',newline='')
            temp.replace(path); print('MODIFICADO:',path)
    except BaseException:
        for path,relative,_ in pending: shutil.copy2(backup/relative,path)
        raise
    print('Parche aplicado. Reinicia las APIs y ejecuta python iniciar_rutinas.py --listar')
if __name__=='__main__': main()
